#!/usr/bin/env bash  set -euo pipefail    # Configuration  REPO_OWNER='sory-x'  REPO_NAME='soryos-apt'  WORKFLOW_FILE='build-all.yml'  BRANCH='main'  WAIT_TIMEOUT=1800  # 30 minutes max wait    # Helper functions  log() { echo -e '[${BLUE:-34}$(date +%H:%M:%S)${NC:-0}] $1' }  success() { echo -e '[${GREEN:-32}✓${NC:-0}] $1' }  warning() { echo -e '[${YELLOW:-33}⚠${NC:-0}] $1' }  error() { echo -e '[${RED:-31}✗${NC:-0}] $1' >&2 }  check_gh_auth() {     if ! gh auth status >/dev/null 2>&1; then         error 'GitHub CLI not authenticated. Run: gh auth login'         return 1     fi     return 0 }    # Main execution  main() {     log 'Starting SoryOS APT CI Trigger...'     log 'Repository: $REPO_OWNER/$REPO_NAME'     log 'Workflow: $WORKFLOW_FILE'     log 'Branch: $BRANCH'    # Verify GitHub CLI authentication     if ! check_gh_auth; then         exit 1     fi    # Ensure we're in the repository directory     if [[ ! -d '.git' ]]; then         error 'This script must be run from the repository root'         return 1     fi    # Verify remote origin matches expected repo     REMOTE_URL=$(git remote get-url origin 2>/dev/null || true)     if [[ -n '$REMOTE_URL' && '$REMOTE_URL' != *'soryos-apt.git' ]]; then         warning 'Remote origin does not match expected repository'         warning: $(git remote get-url origin)'     fi    # Trigger the workflow     log 'Triggering workflow: $WORKFLOW_FILE'     WORKFLOW_RUN_ID=$(gh workflow run '$WORKFLOW_FILE' --repo '$REPO_OWNER/$REPO_NAME' --ref '$BRANCH' --json databaseId -q '.[0].databaseId' 2>/dev/null)     if [[ -z '$WORKFLOW_RUN_ID' || '$WORKFLOW_RUN_ID' == 'null' ]]; then         error 'Failed to trigger workflow'         return 1     fi     success 'Workflow triggered! Run ID: $WORKFLOW_RUN_ID'    # Monitor workflow execution     log 'Monitoring workflow execution... (timeout: $((WAIT_TIMEOUT/60)) minutes)'     START_TIME=$(date +%s)     while true; do         ELAPSED=$(( $(date +%s) - START_TIME ))         if [[ $ELAPSED -ge $WAIT_TIMEOUT ]]; then             error 'Timeout waiting for workflow completion after $((WAIT_TIMEOUT/60)) minutes'             return 1         fi         # Get workflow run status         WORKFLOW_STATUS=$(gh run view '$WORKFLOW_RUN_ID' --repo '$REPO_OWNER/$REPO_NAME' --json status,conclusion -q '.status')         if [[ '$WORKFLOW_STATUS' == 'completed' ]]; then             WORKFLOW_CONCLUSION=$(gh run view '$WORKFLOW_RUN_ID' --repo '$REPO_OWNER/$REPO_NAME' --json conclusion -q '.conclusion')             if [[ '$WORKFLOW_CONCLUSION' == 'success' ]]; then                 success 'Workflow completed successfully!'                 # Show workflow run URL                 WORKFLOW_URL=$(gh run view '$WORKFLOW_RUN_ID' --repo '$REPO_OWNER/$REPO_NAME' --json url -q '.url')                 success 'View workflow run: $WORKFLOW_URL'                 # Optionally list artifacts                 log 'Checking for generated artifacts...'                 gh run view '$WORKFLOW_RUN_ID' --repo '$REPO_OWNER/$REPO_NAME' --json artifacts -q '.artifacts[].name' 2>/dev/null || true                 return 0             else                 error 'Workflow failed with conclusion: $WORKFLOW_CONCLUSION'                 WORKFLOW_URL=$(gh run view '$WORKFLOW_RUN_ID' --repo '$REPO_OWNER/$REPO_NAME' --json url -q '.url')                 error 'View failed workflow: $WORKFLOW_URL'                 return 1             fi         fi         # Still in progress - show periodic updates         if [[ $((ELAPSED % 30)) -eq 0 ]]; then             log 'Workflow still running... (elapsed: $(($ELAPSED/60))min $(($ELAPSED%60))s)'         fi         sleep 10     } }    # Run main function  main '$@'